const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  if (!body.decision_context || typeof body.decision_context !== 'string') return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'decision_context requerido (string explicando que se debe decidir)' } }];
  if (!Array.isArray(body.options) || body.options.length < 2) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'options requerido (array con al menos 2 opciones a comparar)' } }];
  if (body.options.length > 8) return [{ json: { _error: 'TOO_MANY_OPTIONS', _status: 413, _details: 'max 8 opciones a evaluar (recibidas ' + body.options.length + ')' } }];
  const validOrigen = ['arquitecto','cliente','sistema','agente'];
  const decisionOrigen = validOrigen.includes(body.decision_origen) ? body.decision_origen : 'arquitecto';
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    decision_context: body.decision_context,
    options: body.options,
    criterios_prioritarios: Array.isArray(body.criterios_prioritarios) ? body.criterios_prioritarios : [],
    decision_origen: decisionOrigen,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Validate').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
if (projectRows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe', request_id: sess.request_id }}];
const project = projectRows[0];
const briefingRows = $('Load Briefing').all().map(i => i.json).filter(b => b && b.id);
const costRows = $('Load Cost Estimate').all().map(i => i.json).filter(c => c && c.id);
const directiveRows = $input.all().map(i => i.json).filter(d => d && d.directiva);
const briefing = briefingRows[0] || null;
const cost = costRows[0] || null;

const optionsDescriptions = sess.options.map(function(o, i) {
  return (i+1) + '. ' + (o.name || o.id || 'opt_' + i) + ': ' + (o.description || '(sin descripcion)');
}).join('\n');

const directivesText = directiveRows.length
  ? directiveRows.map(function(d) { return '- (' + d.categoria + ', prio ' + d.prioridad + ') ' + d.directiva + (d.contexto ? ' [' + d.contexto + ']' : ''); }).join('\n')
  : '(sin directivas activas)';

const criteriosTexto = sess.criterios_prioritarios.length
  ? sess.criterios_prioritarios.join(', ')
  : 'coste, calidad, plazo, normativa, eficiencia_energetica';

const systemPrompt = 'Eres agent_decision_engine, motor de decisiones del estudio. Tu rol: evaluar opciones presentadas con criterios objetivos y recomendar la mejor opcion, SIN tomar la decision final (el humano firma).\n\nREGLAS DE ORO:\n- Evalua cada opcion contra TODOS los criterios. Da score 0-100 por criterio y total ponderado.\n- Prioriza los criterios que el caller marca como prioritarios.\n- Estima impacto economico (EUR), normativo (texto: cumple/no cumple/condicional) y energetico (texto: clase A/B/C/D segun aplique, o impacto kWh/m2 estimado).\n- Justificacion clara en espanol arquitecto, sin tecnicismos legales.\n- Si una opcion tiene un riesgo critico (incumple normativa, supera 30% del presupuesto, etc.) MARCALO.\n- DEVUELVE SOLO JSON valido.';

const userPrompt = 'CONTEXTO DE DECISION: ' + sess.decision_context + '\n\nPROYECTO: ' + project.name + ' (' + project.project_type + ', ' + (project.property_area_m2 || '?') + ' m2, budget ' + (project.budget_target || '?') + ' EUR)\n' +
  'Ubicacion: ' + (project.location_city || '?') + ', ' + (project.location_province || '?') + '\n' +
  'Fase actual: ' + project.current_phase + '\n\n' +
  'BRIEFING: ' + (briefing && briefing.summary ? briefing.summary.slice(0, 500) : '(sin briefing aprobado)') + '\n' +
  'Constraints: ' + JSON.stringify(briefing && briefing.constraints ? briefing.constraints : []) + '\n\n' +
  'COST ESTIMATE: ' + (cost ? 'v' + cost.version + ', total ' + cost.total_estimated + ' EUR, deviation ' + cost.deviation_status : '(sin cost estimate)') + '\n\n' +
  'OPCIONES A EVALUAR (' + sess.options.length + '):\n' + optionsDescriptions + '\n\n' +
  'CRITERIOS PRIORITARIOS: ' + criteriosTexto + '\n\n' +
  'DIRECTIVAS DEL ESTUDIO:\n' + directivesText + '\n\n' +
  'TAREA: evalua cada opcion contra los criterios y devuelve recomendacion.\n\n' +
  'OUTPUT JSON (estricto, SOLO el JSON):\n' +
  '{ "options_evaluation": [ { "id": "opt_a", "name": "...", "scores": { "coste": 80, "normativa": 100, "eficiencia_energetica": 65 }, "score_total": 81, "impacto_economico_eur": 12500, "impacto_normativo": "cumple CTE HE-1", "impacto_energetico": "clase B", "pros": ["..."], "cons": ["..."], "risk_flags": [] } ], "recomendacion": { "opcion_id": "opt_a", "justificacion": "...", "alternativa_secundaria": "opt_b", "confianza": 0.85 }, "criterios_aplicados": [ { "nombre": "coste", "peso": 0.3 } ], "notas_adicionales": "..." }';

return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  project_id: project.id,
  request_id: sess.request_id,
  decision_context: sess.decision_context,
  options_input: sess.options,
  criterios_prioritarios: sess.criterios_prioritarios,
  decision_origen: sess.decision_origen,
  llm_payload: {
    model: 'gpt-4o',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.2,
    max_tokens: 2500,
    response_format: { type: 'json_object' }
  }
}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id } }];
}
const usage = llm?.usage || {};
const options = Array.isArray(parsed.options_evaluation) ? parsed.options_evaluation : [];
const recommendation = parsed.recomendacion || {};
return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  decision_context: built.decision_context,
  options_input: built.options_input,
  decision_origen: built.decision_origen,
  output: {
    options_evaluation: options,
    recomendacion: recommendation,
    criterios_aplicados: parsed.criterios_aplicados || [],
    notas_adicionales: parsed.notas_adicionales || null
  },
  summary: {
    options_evaluated: options.length,
    recommended_option: recommendation.opcion_id || null,
    confianza: recommendation.confianza || null
  },
  model: llm?.model || 'gpt-4o',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

options.queryReplacement:
={{ [
  $('Start Execution').first().json.id,
  JSON.stringify({ decision_log_id: $json.id, recommended_option: $('Format Response').first().json.summary.recommended_option, confianza: $('Format Response').first().json.summary.confianza, options_evaluated: $('Format Response').first().json.summary.options_evaluated }),
  JSON.stringify({ model: $('Format Response').first().json.model, tokens_in: $('Format Response').first().json.tokens_in, tokens_out: $('Format Response').first().json.tokens_out, eu_ai_act: 'recomendacion supervisada por humano (arquitecto/cliente firma)' })
] }}
